// @vitest-environment node
// Shared harness for Container API render tests.
//
// Vitest's default `happy-dom` environment stubs `.astro` module imports to a
// browser only errored shell ("Astro components cannot be used in the
// browser"). Per-file `@vitest-environment node` lets the Astro Vite plugin
// emit the SSR component factory instead.
//
// `Astro.site` is left `undefined` by `experimental_AstroContainer.create()`
// (the container config defaults elide `site`). Components that compute
// canonical URLs against `Astro.site` — `MetaTags.astro` in particular —
// throw `new URL(path, undefined)`. Components whose frontmatter doesn't
// depend on `Astro.site` render unchanged; components that pull in `Layout`
// mock `@/components/common/MetaTags.astro` against `./stubs/MetaTagsStub.astro`
// to stay off the unhappy path.
import { experimental_AstroContainer as AstroContainer } from 'astro/container'
import { load as cheerioLoad, type CheerioAPI } from 'cheerio'

let containerPromise: Promise<experimental_AstroContainer> | undefined

export async function getContainer(): Promise<experimental_AstroContainer> {
  if (!containerPromise) containerPromise = AstroContainer.create()
  return containerPromise
}

export async function render(
  Component: Parameters<experimental_AstroContainer['renderToString']>[0],
  options?: Parameters<experimental_AstroContainer['renderToString']>[1],
): Promise<{ html: string; $: CheerioAPI }> {
  const container = await getContainer()
  const html = await container.renderToString(Component, options)
  return { html, $: cheerioLoad(html) }
}

// @vitest-environment node
import { describe, expect, it } from 'vitest'
import Button from '@/components/controls/Button.astro'
import { render } from '../lib/container'

describe('Button.astro', () => {
  it('renders an anchor when El is unset (default), with href and slotted label', async () => {
    const { $ } = await render(Button, {
      props: { href: '/foo', emphasis: 'primary' },
      slots: { default: 'Mehr' },
    })
    expect($('a')).toHaveLength(1)
    expect($('a').attr('href')).toBe('/foo')
    expect($('a').text()).toContain('Mehr')
  })

  it('renders a <button type="submit"> when El="button" and type="submit"', async () => {
    const { $ } = await render(Button, {
      props: { El: 'button', type: 'submit', emphasis: 'primary' },
      slots: { default: 'Senden' },
    })
    expect($('button[type="submit"]')).toHaveLength(1)
    expect($('button').text()).toContain('Senden')
    expect($('a')).toHaveLength(0)
  })

  it('reflects the disabled attribute onto the button element', async () => {
    const { $ } = await render(Button, {
      props: { El: 'button', type: 'submit', disabled: true },
      slots: { default: 'x' },
    })
    expect($('button[disabled]')).toHaveLength(1)
  })

  it('forwards the optional id prop', async () => {
    const { $ } = await render(Button, {
      props: { id: 'cta' },
      slots: { default: 'go' },
    })
    expect($('#cta')).toHaveLength(1)
  })

  it('renders a single child span (no fragment-level elements leak)', async () => {
    const { $ } = await render(Button, { slots: { default: 'x' } })
    expect($('a > span')).toHaveLength(1)
    expect($('a > div')).toHaveLength(0)
  })
})

