    expect($('button span')).toHaveLength(2)
    // SubmitButton nests a spinner span inside Button's wrapper span, so the
    // button contains exactly two nested <span> elements — the outer one from
    // Button's Em wrapper, the inner one from SubmitButton's flex row that
    // holds the SVG and the slot text. The deepest <span> — the spinner
    // container — has the SVG as a direct child, with the slot text rendering
    // as a trailing text node.
    const spinnerSpan = $('button span > svg').parent()
    expect(spinnerSpan).toHaveLength(1)
    expect(spinnerSpan.children().first().prop('tagName')?.toLowerCase()).toBe('svg')
  })

